// Only the visible top faces of the owning tile may receive its number.
export function topFaceIndices(mesh){const top=Math.max(...mesh.positions.filter((_,i)=>i%3===1)),indices=[];for(let i=0;i<mesh.indices.length;i+=3){const t=mesh.indices.slice(i,i+3);if(t.every(j=>Math.abs(mesh.positions[j*3+1]-top)<.0001))indices.push(...t);}return indices;}
export function makeLabelTexture(text,label){const scale=128,w=text.rect.sizeDelta.x,h=text.rect.sizeDelta.y,canvas=document.createElement('canvas');canvas.width=Math.ceil(w*scale);canvas.height=Math.ceil(h*scale);const ctx=canvas.getContext('2d'),settings=text.settings,colors=Object.fromEntries(text.material?.colors || []),rgb=c=>`rgb(${Math.round(c.r*255)},${Math.round(c.g*255)},${Math.round(c.b*255)})`;let size=settings.m_fontSize/10*scale;const min=(settings.m_fontSizeMin || settings.m_fontSize)/10*scale;const measure=()=>{ctx.font=`700 ${size}px ShinBoardNumbers`;const chars=[...label],tracking=size*(settings.m_characterSpacing || 0)/100;return{chars,tracking,width:chars.reduce((n,c)=>n+ctx.measureText(c).width,0)+Math.max(0,chars.length-1)*tracking};};let layout=measure();if(settings.m_enableAutoSizing&&layout.width>canvas.width-scale*.06){size=Math.max(min,size*(canvas.width-scale*.06)/layout.width);layout=measure();}const metrics=ctx.measureText(label),baseline=canvas.height/2+(metrics.actualBoundingBoxAscent-metrics.actualBoundingBoxDescent)/2;ctx.lineWidth=.055*scale;ctx.strokeStyle=rgb(colors._OutlineColor || {r:.55,g:.55,b:.55});ctx.fillStyle=rgb(colors._FaceColor || {r:.537,g:.525,b:.529});let x=(canvas.width-layout.width)/2;for(const char of layout.chars){ctx.strokeText(char,x,baseline);ctx.fillText(char,x,baseline);x+=ctx.measureText(char).width+layout.tracking;}return canvas;}
